import { test, expect } from '@playwright/test';

test.describe('Image Paste from Clipboard into Upload Area', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/upload');
  });

  test('should successfully paste an image from the clipboard into the upload area', async ({ page }) => {
    // Verify upload button is visible
    const uploadButton = page.getByRole('button', { name: /upload/i });
    await expect(uploadButton).toBeVisible();

    // Verify upload area is visible
    const uploadArea = page.getByRole('region', { name: /upload area/i });
    await expect(uploadArea).toBeVisible();

    // Verify paste button is visible
    const pasteButton = page.getByRole('button', { name: /paste/i });
    await expect(pasteButton).toBeVisible();

    // Verify upload area has placeholder text
    const placeholderText = page.getByText(/paste image/i);
    await expect(placeholderText).toBeVisible();

    // Verify upload area has no file input
    const fileInput = page.getByRole('input', { name: /file/i });
    await expect(fileInput).not.toBeVisible();

    // Verify upload button is enabled
    await expect(uploadButton).toBeEnabled();

    // Verify paste button is enabled
    await expect(pasteButton).toBeEnabled();

    // Verify upload area has no error message
    const errorMessage = page.getByText(/error/i);
    await expect(errorMessage).not.toBeVisible();

    // Paste image using keyboard shortcut (Ctrl+V)
    await page.keyboard.press('Ctrl+V');

    // Verify file input appears
    await expect(fileInput).toBeVisible();

    // Verify file input has the correct file type
    const fileInputValue = await fileInput.evaluate((el) => el.value);
    expect(fileInputValue).toContain('image/png');

    // Verify upload button is now disabled
    await expect(uploadButton).not.toBeEnabled();

    // Verify paste button is now disabled
    await expect(pasteButton).not.toBeEnabled();

    // Verify upload area shows success message
    const successMessage = page.getByText(/upload successful/i);
    await expect(successMessage).toBeVisible();

    // Verify file input has the correct file name
    const fileName = await fileInput.evaluate((el) => el.files[0].name);
    expect(fileName).toBe('test-image.png');
  });

